Q: How to get MemoryStream (or another Stream) from Memory&lt;byte&gt; without reallocating? A: <p>It is possible by using <a href="https://www.nuget.org/packages/CommunityToolkit.HighPerformance/" rel="nofollow noreferrer">CommunityToolkit.HighPerformance</a> NuGet package:</p>
<pre class="lang-cs prettyprint-override"><code>using CommunityToolkit.HighPerformance;

var memory = new ReadOnlyMemory&lt;byte&gt;(new byte[] { 1, 2, 3, 4 });
var stream = memory.AsStream();
</code></pre>

Q: How can I add SQLite to Data Source Wizard in Visual Studio 2022? A: <p>This doesn't add it to the Data Source but the easiest way I found was:</p>
<pre><code>using System.Data.SQLite;

namespace younamespace {
  class YourClass {
    public void Foo() {
      string db_name = &quot;databasename.ext&quot;; //ext is either .db or .sqlite3
      string connectionString = $&quot;{Path.Combine(Environment.CurrentDirectory, db_name)}&quot;;
      SQLiteConnection myDatabase = new SQLiteConnection(connectionString);
      myDatabase.Open();
      //VS will give an error to the '.Open()' method and a quick fix to solve the issue
      SQLiteCommand sqlCmd = myDatabase.CreateCommand();
      sqlCmd.CommandText = @&quot;insert sql command here&quot;;
      sqlCmd.CommandType = CommandType.Text;

      SQLiteDataReader reader = sqlCmd.ExecuteReader();
      while(reader.Read()) {
        datatype varName = reader[&quot;tableHeading&quot;];
        //...etc
      }
      myDatabase.Close();
    }
  }
}
</code></pre>
<p>You need to remember this every time you use it. As an SQLite class:</p>
<pre><code>using System.Data.SQLite;
namespace yournamespace {
  class SQLiteClass {
    private SQLiteConnection connection;
    public SQLiteClass() {
      string dbName = &quot;name.ext&quot;;
      string connectionString = $&quot;{Path.Combine(Environment.CurrentDirectory, dbName)}&quot;;
      this.connection = new SQLiteConnection(connectionString);
     }

     public returnType runCmd(string sCmd) {
       this.connection.Open();
       SQLiteCommand sqlCmd = this.connection.CreateCommand();
       sqlCmd.CommandText = sCmd;
       sqlCmd.CommandType = CommandType.Text;

      SQLiteDataReader reader = sqlCmd.ExecuteReader();
      returnType result = new returnType();
      while(reader.Read()) {
        //...etc
      }
      this.connection.Close();
      return result;
    }
  }
}
</code></pre>

